import {allExams,artwork} from './public-data.mjs';
import {libraryLayout,renderLibraryResults} from './library.mjs';
import {renderShell} from './learning-shell.mjs';
import {attemptCTA,dashboardOverview,uiIcon} from './learning-ui.mjs';
import {requireLeadAccess} from './lead-gate.mjs';
import {api} from './client-api.mjs';
import {matchScene,paintScene,pictureTools,bindPictureInteractions} from './picture-ui.mjs';
import {mediaImage,artworkImage} from './media.mjs';

const root=document.querySelector('#app'),modal=document.querySelector('#modal'),audio=document.querySelector('#audio');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=new URLSearchParams(location.search);
let session={user:null,registered:false,databaseReady:false},exam=allExams.find(e=>e.id===initial.get('test'))||allExams[0];
let screen=initial.get('screen')||'dashboard',skill=initial.get('skill')==='listening'?'listening':'reading',partIndex=Math.max(0,Number(initial.get('part'))||0);
let attempt=null,answers={},writing={},selectedName='',tool='colour',color='blue',wordArea='',undo=[],audioSource='',draftTimer=null,pendingDraft=null,category='all',query='',limit=6,boardLevel='starters',boardExam='starters-01',boardEntries=[],history=[],staff=null,staffStudent='',staffAttempts=[],selectedStaffAttempt=null,review=null,errorMessage='',busy=false,saveMessage='Saved on this device',gatePromise,reviewTimer=null;
let historyAvailable=true;
let activityRequest=0,boardRequest=0;
let activities=[],activityStatus='all',activityStudent='',activityOffset=0,activityAvailable=true;
boardExam=allExams.find(e=>e.levelKey===boardLevel)?.id||allExams[0].id;
const byId=id=>document.getElementById(id);
const icons={arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',book:'<path d="M12 5v15M12 5C9 3 5 3 3 4v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-2-1-6-1-9 1Z"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 12h3v8H5a2 2 0 0 1-2-2v-4a2 2 0 0 1 1-2Zm16 0h-3v8h2a2 2 0 0 0 2-2v-4a2 2 0 0 0-1-2Z"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
const currentPart=()=>exam[skill][Math.min(partIndex,exam[skill].length-1)];
const examLabel=e=>`${e.level}${e.difficulty?' · '+e.difficulty:''} · ${e.levelKey==='starters'?'Test':'Mock'} ${e.number}`;
const localKey=()=>`wewin-platform-${session.user?.id||'guest'}-${exam.id}-${exam.version}`;
const image=(src,alt='',cls='')=>mediaImage(src,alt,{className:cls});
const button=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const announce=message=>{byId('announcer').textContent=message;};
function notify(error){errorMessage=error.message||String(error);const target=byId('screen-error');if(target){target.textContent=errorMessage;target.hidden=false;}announce(errorMessage);}
const footer=()=>`<footer class="site-footer"><span>© 2026 WeWIN Education</span><span>${['exam','intro','result','board'].includes(screen)?'WeWIN practice material · Not an official Cambridge exam':'Tài liệu luyện tập WeWIN · Không phải đề thi chính thức Cambridge'}</span></footer>`;
function catalogAction(e){return attemptCTA(e,history);}
function catalogResults(){return renderLibraryResults({category,query,limit,action:catalogAction,attempts:history});}
function render(){
 const focused=document.documentElement.dataset.input==='keyboard'&&root.contains(document.activeElement)?document.activeElement:null;
 const focusData=focused?.dataset?.action?{...focused.dataset}:null,focusId=focused?.id;
 document.body.dataset.screen=screen;document.documentElement.lang=['catalog','dashboard','history','staff','login'].includes(screen)?'vi':'en';
 const params=new URLSearchParams({screen});if(['intro','exam','result'].includes(screen)){params.set('test',exam.id);params.set('skill',skill);params.set('part',partIndex);if(attempt?.id)params.set('attempt',attempt.id);}window.history.replaceState(null,'','?'+params);
 const error=`<p id="screen-error" class="screen-error" role="alert" ${errorMessage?'':'hidden'}>${esc(errorMessage)}</p>`;
 const content=screen==='catalog'?error+libraryLayout({category,query,results:catalogResults(),attempts:history,user:session.user,available:historyAvailable}):`<div class="platform-shell">${error}${screen==='intro'?introView():screen==='exam'?examView():screen==='result'?resultView():screen==='staff'?staffView():screen==='login'?loginView():dashboardView()}</div>`;
 root.innerHTML=renderShell({screen,category,session,exams:allExams,attempts:history,available:historyAvailable,content,footer:footer()});
 if(focusId)byId(focusId)?.focus({preventScroll:true});
 if(focusData)[...root.querySelectorAll('[data-action]')].find(el=>Object.entries(focusData).every(([key,value])=>el.dataset[key]===value))?.focus({preventScroll:true});
 syncAudio();if(screen==='exam'&&currentPart().interaction)bindPictureInteractions(root,{part:currentPart(),selectName,connect,region:selectRegion});
 if(screen==='result'||screen==='board')renderBoardInto();
}
function navigate(next){clearTimeout(reviewTimer);errorMessage='';screen=next;render();window.scrollTo({top:0,behavior:'instant'});if(document.documentElement.dataset.input==='keyboard')byId('main-content')?.focus({preventScroll:true});}
async function refreshHistory(){if(!session.registered||session.user&&session.user.role!=='student'){history=[];historyAvailable=true;return;}try{history=(await api('history')).attempts;historyAvailable=true;}catch{historyAvailable=false;}}
function introView(){const count=exam.reading.filter(p=>p.manual).length;return `<div class="intro-grid"><section class="intro-picture">${image(exam.cover,exam.title)}</section><section class="intro-copy"><div class="eyebrow">${examLabel(exam)}</div><h1>${esc(exam.title)}</h1><p>Practise Reading & Listening with pictures and audio.</p><div class="intro-stats"><div class="intro-stat">${icon('book')}<strong>Reading</strong><small>${exam.readingCount} automatically marked questions</small></div><div class="intro-stat">${icon('headphones')}<strong>Listening</strong><small>${exam.listeningCount} questions</small></div></div><div class="instructions"><p>You can pause and listen again.</p><p>Answer the questions, draw lines and colour in the picture.</p><p>Your first submitted attempt is used for the student leaderboard.</p>${count?`<p>Open writing is assessed separately. ${session.user?.role==='student'?'AI feedback is available after you submit.':'Please contact WeWIN to access AI Writing assessment.'}</p>`:''}</div>${button(busy?'Opening your attempt…':'Start practice','start','primary full',busy?'disabled':'')}<p class="small muted">The score is a WeWIN practice score. It is not converted to Cambridge shields.</p></section></div>`;}
function art(spec,alt){return spec?artworkImage(spec,alt):'';}
function partInstruction(p){if(p.instruction)return p.instruction;if(skill==='listening')return ['Listen and draw lines. There is one example.','Listen and write one word or a number.','Listen and write a letter in each box.','Listen and choose the correct picture.','Listen, colour and write. There is one example.'][partIndex];return 'Read the instructions in the picture and answer the questions.';}
function figure(p){
 if(p.interaction)return `<div class="picture-toolbar"><strong>${p.interaction.type==='match'?'Draw lines':'Colour & write'}</strong>${button('Zoom','zoom-picture','ghost')}</div><div class="picture-stage">${p.interaction.type==='match'?matchScene(p,answers[p.id]||{},selectedName):paintScene(p,answers[p.id]||{})}</div>`;
 const context=p.contextTitle?`<div class="story-context"><strong>${esc(p.contextTitle)}</strong>${p.characters?.length?`<span>Characters: ${p.characters.map(esc).join(' · ')}</span>`:''}</div>`:'';
 if(p.images?.length)return context+p.images.map((src,i)=>`<button class="mover-page" data-action="zoom-page" data-image="${src}" aria-label="Enlarge question page ${i+1}">${image(src,`Part ${partIndex+1}, page ${i+1}`)}</button>`).join('');
 if(p.image)return image(p.image,'Picture for this part','question-picture');
 if(p.storyArts)return p.storyArts.map((spec,i)=>`<figure class="story-item"><figcaption>Picture ${i+1}</figcaption>${art(spec,`Picture ${i+1}`)}</figure>`).join('');
 if(p.bank)return `<h3>${esc(p.passageTitle||p.title)}</h3><p class="example">Example: ${esc(p.example||'')}</p><div class="word-bank">${p.bank.map(word=>`<span>${esc(word)}</span>`).join('')}</div>`;
 if(p.questions.some(q=>q.art))return `<div class="question-art-gallery">${p.questions.map((q,i)=>`<figure><figcaption>${i+1}</figcaption>${art(artwork[q.art],q.prompt)}</figure>`).join('')}</div>`;
 return `<div class="listening-guide">${icon('headphones')}<div><h3>Listen carefully</h3><p>The recording includes an example and two listenings.</p></div></div>${image('win.png','Win, your learning companion','mini-art')}`;
}
function question(q,i,p){const value=(p.manual?writing:answers)[q.id]||'';let field;
 if(q.choiceArts)field=`<div class="picture-options">${q.choiceArts.map((key,j)=>`<button class="picture-choice ${value==='ABC'[j]?'selected':''}" data-action="answer" data-question="${q.id}" data-value="${'ABC'[j]}" aria-label="Question ${i+1}, option ${'ABC'[j]}" aria-pressed="${value==='ABC'[j]}"><span class="option-art">${art(artwork[key],`Option ${'ABC'[j]}`)}</span><span>${'ABC'[j]}${value==='ABC'[j]?' ✓':''}</span></button>`).join('')}</div>`;
 else if(q.choices?.length||p.options?.length){const choices=q.choices||p.options.map(c=>({value:c[0],label:c[2]}));field=`<div class="choice-group mover-choices">${choices.map(c=>{const id=typeof c==='string'?c:c.value,label=typeof c==='string'?c:c.label;return `<button class="choice" data-action="answer" data-question="${q.id}" data-value="${esc(id)}" aria-pressed="${value===id}">${esc(label)}</button>`;}).join('')}</div>`;}
 else field=p.manual?`<textarea class="answer-input writing-answer" data-writing="${q.id}" id="answer-${q.id}" rows="${exam.levelKey==='flyers'?9:3}" maxlength="6000" aria-label="${esc(q.prompt)}" placeholder="Write your answer in English">${esc(value)}</textarea>${exam.levelKey==='flyers'?`<p class="word-count" id="words-${q.id}">${wordCount(value)} words · Write 20 or more words</p>`:''}`:`<input class="answer-input" id="answer-${q.id}" data-question="${q.id}" type="text" maxlength="160" autocomplete="off" spellcheck="false" aria-label="${esc(q.prompt)}" placeholder="Write your answer" value="${esc(value)}">`;
 return `<div class="question-row"><div class="question-header"><span class="question-number">${i+1}</span><label for="answer-${q.id}" class="question-prompt">${esc(q.prompt)}</label></div>${field}</div>`;
}
const wordCount=value=>String(value).trim().split(/\s+/).filter(Boolean).length;
function audioPanel(){return `<div class="audio-panel"><button class="audio-button" data-action="play" id="audio-play" aria-label="${audio.paused?'Play audio':'Pause audio'}">${audio.paused?'▶':'❚❚'}</button><div class="audio-label"><strong>Listening · Part ${partIndex+1}</strong><span>Listen and answer the questions</span></div><div class="audio-track"><input type="range" id="audio-seek" min="0" max="1" value="0" step=".1" aria-label="Seek audio"><span class="audio-time" id="audio-time">00:00 / --:--</span></div>${button('Listen from the start','restart-audio','ghost')}<span class="audio-error" id="audio-error" role="alert" hidden></span></div>`;}
function examView(){const p=currentPart();const areas=answers[p.id]||{};return `<div class="exam-top"><div><div class="eyebrow">${examLabel(exam)}</div><h1>${esc(exam.title)}</h1></div><span class="save-status" id="save-status">${esc(saveMessage)}</span></div><div class="skill-tabs">${[['reading','Reading & Writing'],['listening','Listening']].map(([id,label])=>`<button class="skill-tab ${skill===id?'active':''}" data-action="skill" data-value="${id}">${label}</button>`).join('')}</div><div class="part-toolbar"><div class="part-tabs" role="group" aria-label="Parts">${exam[skill].map((p,i)=>`<button class="part-tab ${i===partIndex?'active':''}" data-action="part" data-value="${i}" aria-pressed="${i===partIndex}">Part ${i+1}${p.manual?' · Writing':''}</button>`).join('')}</div>${button('Submit practice','submit','primary')}</div><div class="part-title"><div><h2>Part ${partIndex+1} · ${esc(p.title)}</h2><p>${esc(partInstruction(p))}</p>${p.context?`<p class="part-context">${esc(p.context)}</p>`:''}</div></div>${skill==='listening'?audioPanel():''}${p.manual?'<p class="writing-note">This writing task is assessed separately from Reading & Listening.</p>':''}<div class="exercise-grid ${p.interaction?'picture-exercise':''}"><section class="figure-panel">${figure(p)}</section><section class="question-panel">${p.interaction?pictureTools(p,{selectedName,tool,color,wordArea,areas,canUndo:undo.length>0}):`<div class="answer-heading"><strong>Your answers</strong><span class="small muted">Follow the question numbers</span></div>${p.questions.map((q,i)=>question(q,i,p)).join('')}`}</section></div><div class="exercise-footer">${button('Previous part','previous','',partIndex===0?'disabled':'')}<span class="small muted">Your answers are saved automatically.</span>${button(partIndex===exam[skill].length-1?'Submit practice':'Next part','next')}</div>`;}
function readable(value){if(value&&typeof value==='object')return [value.target,value.color||value.word].filter(Boolean).join(' · ');return value||'Not answered';}
function objectiveReview(result){return `<section class="answer-review"><h2>Reading & Listening · Chi tiết từng câu</h2>${['reading','listening'].map(s=>`<details><summary>${s==='reading'?'Reading':'Listening'} · ${result[s].correct}/${result[s].total} câu đúng</summary>${result.review.filter(q=>q.skill===s).map((q,i)=>`<div class="review-row"><span><strong>${i+1}.</strong> ${esc(q.prompt)}</span><div><small>Bài làm</small><p>${esc(readable(q.value))}</p><small>Đáp án</small><p>${esc(readable(q.expected))}</p></div><strong class="${q.correct?'correct-mark':'incorrect-mark'}">${q.correct?'✓ Đúng':'× Chưa đúng'}</strong></div>`).join('')}</details>`).join('')}</section>`;}
function scoreCards(result){return `<div class="score-grid"><section class="score-card total"><div class="score-label">WeWIN practice score</div><div class="score-number">${result.total}<span> / 100</span></div><p>Reading 50% · Listening 50%</p></section>${['reading','listening'].map(s=>`<section class="score-card"><div class="score-label">${s==='reading'?'Reading':'Listening'}</div><div class="score-number">${result[s].score}<span> / 50</span></div><p>${result[s].correct}/${result[s].total} correct answers</p></section>`).join('')}</div>`;}
function feedbackView(r){if(!r)return '<p class="muted">AI feedback will appear here after assessment.</p>';const v=r.teacher_override||r.original;if(!v)return `<p class="muted">${r.status==='failed'?'The AI service could not assess this writing. Your text is saved. You can try again.':'AI Writing assessment is in progress…'}</p>`;return `<div class="ai-feedback"><div class="ai-feedback-heading"><h3>Writing feedback</h3><span>${r.teacher_override?'Teacher reviewed':'AI practice feedback'} · ${v.score}/${v.maxScore}</span></div><section><h4>1. Mức độ hoàn thành</h4><p>${esc(v.completion)}</p></section><section><h4>2. Ngữ pháp & chính tả</h4>${v.corrections.length?v.corrections.map(c=>`<div class="correction"><p><span>Bé viết:</span> ${esc(c.original)}</p><p><span>Gợi ý sửa:</span> ${esc(c.corrected)}</p><p>${esc(c.explanation)}</p></div>`).join(''):'<p>Không có lỗi cụ thể cần sửa trong phần nhận xét này.</p>'}</section><section><h4>3. Từ vựng</h4>${v.vocabulary.map(x=>`<p>${esc(x)}</p>`).join('')}</section><section><h4>4. Điểm luyện tập</h4><p>${v.score}/${v.maxScore} · Đây là nhận xét luyện tập, không phải điểm Cambridge chính thức.</p></section><details><summary>5. Bài viết tham khảo</summary><p class="sample-writing">${esc(v.sample||'Bé hãy hoàn thành bài trước để nhận ví dụ tham khảo.')}</p></details></div>`;}
function writingView(){const p=exam.reading.find(p=>p.manual);if(!p)return '';const guest=!session.user||session.user.role!=='student';return `<section class="writing-result"><h2>Writing · ${esc(p.title)}</h2>${p.questions.map(q=>`<div class="submitted-writing"><h3>${esc(q.prompt)}</h3><p>${esc(attempt.writing?.[q.id]||'Not answered')}</p></div>`).join('')}${guest?`<div class="writing-access"><strong>Please contact WeWIN to use AI Writing assessment.</strong><p>Vui lòng liên hệ WeWIN để sử dụng tính năng này.</p><a class="btn" href="https://wewin.edu.vn/" target="_blank" rel="noopener">Contact WeWIN</a></div>`:`<div id="ai-feedback">${feedbackView(review)}</div>${button(review?.status==='completed'?'View saved feedback':review?.status==='processing'?'Checking writing…':'Assess my writing','assess-writing','',review?.status==='processing'?'disabled':'')}`}</section>`;}
function resultView(){const result=attempt?.result;if(!result)return '<p>Your result is not available yet.</p>';return `<div class="result-heading"><div class="eyebrow">${examLabel(exam)} · ${exam.title}</div><h1>${session.user?esc(session.user.nickname)+', here are your results.':'Here are your results.'}</h1><p class="result-submitted">${uiIcon('check')} Practice complete · ${formatDate(attempt.submitted_at)}</p></div>${scoreCards(result)}<p class="result-note">Writing is assessed separately. This practice score is not converted to Cambridge shields.</p><div class="result-actions">${button('Choose another test','catalog')}${button('Practise again','retry','primary')}</div>${writingView()}<section class="leaderboard-section"><h2>Leaderboard · ${exam.level}</h2><p class="muted">First submitted attempt for this test. Registered students only.</p><div id="board-results">Loading leaderboard…</div></section><section class="answer-review"><h2>Review your answers</h2>${['reading','listening'].map(s=>`<details><summary>${s==='reading'?'Reading':'Listening'}</summary>${result.review.filter(q=>q.skill===s).map(q=>`<div class="review-row"><span>${esc(q.prompt)}</span><div><small>Your answer</small><p>${esc(readable(q.value))}</p><small>Expected answer</small><p>${esc(readable(q.expected))}</p></div><strong class="${q.correct?'correct-mark':'incorrect-mark'}">${q.correct?'Correct':'Not correct'}</strong></div>`).join('')}</details>`).join('')}</section>`;}
function boardControls(){return `<div class="board-controls"><label>Level<select id="board-level">${[['starters','Pre A1 Starters'],['movers','A1 Movers'],['flyers','A2 Flyers']].map(([id,title])=>`<option value="${id}" ${boardLevel===id?'selected':''}>${title}</option>`).join('')}</select></label><label>Test<select id="board-exam">${allExams.filter(e=>e.levelKey===boardLevel).map(e=>`<option value="${e.id}" ${boardExam===e.id?'selected':''}>${e.levelKey==='starters'?'Test':'Mock'} ${e.number} · ${esc(e.title)}</option>`).join('')}</select></label></div>`;}
function historyTable(items,staffMode=false){return items.length?`<div class="attempt-list">${items.map(a=>{const e=allExams.find(e=>e.id===a.exam_id);return `<article class="attempt-row"><span class="attempt-state-icon ${a.submitted_at?'tone-mint':'tone-blue'}">${uiIcon(a.submitted_at?'check':'clock')}</span><div class="attempt-row-copy"><span class="page-overline">${esc(e?.level||'Cambridge')} · ${esc(e?.number||'')}</span><h3>${esc(e?.title||a.exam_id)}</h3><p>${a.submitted_at?'Đã nộp bài':'Đang làm'} · ${formatDate(a.submitted_at||a.created_at)}</p></div>${a.result?`<div class="attempt-score"><strong>${Number(a.result.total)}<small>/100</small></strong><span>R ${a.result.reading.score}/50 · L ${a.result.listening.score}/50</span></div>`:'<span class="draft-badge">Bài nháp</span>'}${button((a.submitted_at?'Xem kết quả':'Tiếp tục')+' '+uiIcon('arrow'),staffMode?'staff-attempt':'load-attempt','ghost',`data-id="${esc(a.id)}" ${!e?'disabled':''}`)}</article>`;}).join('')}</div>`:`<div class="history-empty">${uiIcon('book')}<h3>Hành trình bắt đầu từ bài đầu tiên</h3><p>${session.registered?'Chọn một đề phù hợp. Bài đang làm và kết quả sẽ được lưu tại đây.':'Điền thông tin phụ huynh hoặc đăng nhập để bắt đầu luyện tập.'}</p>${button('Khám phá đề luyện '+uiIcon('arrow'),'catalog','primary')}</div>`;}
const formatDate=value=>value?new Date(value).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
function dashboardView(){if(screen==='history')return `<div class="page-heading"><div><p class="page-overline">Bài làm của bạn</p><h1>Kết quả luyện thi</h1><p>Xem điểm, đọc lại đáp án và tiếp tục các bài đang làm.</p></div>${button('Làm mới','refresh-history','ghost')}</div><section class="attempt-history">${historyAvailable?historyTable(history):'<p class="empty-copy">Chưa tải được bài làm. Vui lòng thử làm mới.</p>'}</section>`;if(screen!=='board')return dashboardOverview({exams:allExams,attempts:history,user:session.user,available:historyAvailable,historyHTML:historyTable(history)});return `<div class="page-heading"><div><p class="page-overline">WeWIN Cambridge</p><h1>Student leaderboard</h1><p>Compare first submitted attempts on the same practice test.</p></div><span class="workspace-label">${uiIcon('trophy')} Reading & Listening</span></div><section class="leaderboard-section board-panel"><div class="section-heading"><h2>First-attempt leaderboard</h2><span class="board-fairness">${uiIcon('shield')} First attempt only</span></div>${boardControls()}<div id="board-results" aria-live="polite">Loading leaderboard…</div><p class="result-note">Writing is assessed separately. Practice scores are not Cambridge shields.</p></section>`;}
function renderBoardInto(){const target=byId('board-results');if(!target)return;target.innerHTML=boardEntries===null?'<p class="empty-copy">Leaderboard is unavailable. Please try again later.</p>':!boardEntries.length?'<p class="empty-copy">No ranked attempts for this test yet.</p>':`<div class="table-scroll"><table class="results-table"><thead><tr><th>Rank</th><th>Nickname</th><th>Reading /50</th><th>Listening /50</th><th>Total /100</th></tr></thead><tbody>${boardEntries.map(r=>`<tr><td>${r.rank}</td><td>${esc(r.nickname)}</td><td>${Number(r.reading_score)}</td><td>${Number(r.listening_score)}</td><td><strong>${Number(r.total_score)}</strong></td></tr>`).join('')}</tbody></table></div>`;}
async function loadBoard(){const request=++boardRequest;const target=byId('board-results');if(target)target.textContent='Loading leaderboard…';try{const result=await api('leaderboard',{exam:screen==='result'?exam.id:boardExam});if(request!==boardRequest)return;boardEntries=result.entries;}catch{if(request!==boardRequest)return;boardEntries=null;}renderBoardInto();}
function loginView(){const en=['intro','exam','result','board'].includes(screen);return `<div class="login-panel"><h1>${en?'Sign in to WeWIN':'Đăng nhập WeWIN'}</h1><p>${en?'Use the account provided by WeWIN. Guests can continue with parent registration.':'Tài khoản do Admin WeWIN cấp. Guest có thể tiếp tục điền form phụ huynh.'}</p><form id="login-form"><label>${en?'Username':'Tài khoản'}<input name="username" autocomplete="username" required maxlength="80"></label><label>${en?'Password':'Mật khẩu'}<input type="password" name="password" autocomplete="current-password" required maxlength="128"></label><p class="form-error" role="alert"></p><button class="btn primary" type="submit">${en?'Sign in':'Đăng nhập'}</button></form></div>`;}
function openModal(html,cls=''){modal.className=cls;modal.innerHTML=html;const heading=modal.querySelector('h2');if(heading)heading.id='modal-title';if(!modal.open)modal.showModal();}
function showLogin(){const en=['intro','exam','result','board'].includes(screen);openModal(`<div class="zoom-header"><h2>${en?'Sign in to WeWIN':'Đăng nhập WeWIN'}</h2>${button(en?'Close':'Đóng','close-modal','ghost')}</div>${loginView()}`);modal.querySelector('[name="username"]')?.focus();}
function showPassword(){openModal(`<h2>Change your temporary password</h2><p>Choose a password of at least 10 characters before using your account.</p><form id="password-form"><label>Current password<input type="password" name="currentPassword" autocomplete="current-password" required></label><label>New password<input type="password" name="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><p class="form-error" role="alert"></p><button class="btn primary" type="submit">Save new password</button></form>`);}
async function loadActivity(){const request=++activityRequest;try{const result=await api('activity',{student:activityStudent,status:activityStatus,offset:activityOffset});if(request!==activityRequest)return false;activities=result.activities;activityAvailable=true;}catch{if(request!==activityRequest)return false;activityAvailable=false;}return true;}
function activityView(){return `<section id="staff-activity" class="management-block"><div class="section-heading"><div><p class="page-overline">Theo dõi luyện thi</p><h2>Nhật ký bài làm</h2></div>${button('Làm mới','refresh-activity','ghost')}</div><p class="activity-caption">${session.user?.role==='admin'?'Bài làm của học viên và khách đã đăng ký.':'Bài làm của học sinh trong các lớp bạn được phân công.'} Thời gian hiển thị theo giờ Việt Nam. Gồm mốc bắt đầu và nộp bài được hệ thống lưu.</p><div class="activity-filters"><label>Học viên<select id="activity-student"><option value="">Tất cả học viên</option>${(staff?.users||[]).filter(u=>u.role==='student').map(u=>`<option value="${u.id}" ${activityStudent===u.id?'selected':''}>${esc(u.nickname)}</option>`).join('')}</select></label><label>Trạng thái<select id="activity-status"><option value="all" ${activityStatus==='all'?'selected':''}>Tất cả bài làm</option><option value="draft" ${activityStatus==='draft'?'selected':''}>Đang làm</option><option value="submitted" ${activityStatus==='submitted'?'selected':''}>Đã nộp</option></select></label></div><div id="activity-results">${activityResults()}</div></section>`;}
function activityResults(){if(!activityAvailable)return `<p class="empty-copy" role="status">Chưa tải được nhật ký. Vui lòng thử làm mới.</p>`;return activities.length?`<div class="table-scroll"><table class="results-table activity-table"><caption class="sr-only">Nhật ký bài làm · ${activityOffset+1} đến ${activityOffset+activities.length}</caption><thead><tr><th scope="col">Thời gian</th><th scope="col">Học viên</th><th scope="col">Bài luyện</th><th scope="col">Trạng thái</th><th scope="col">Điểm</th><th scope="col">Chi tiết</th></tr></thead><tbody>${activities.map(a=>{const e=allExams.find(e=>e.id===a.exam_id);return `<tr><td>${formatDate(a.created_at)}<small>Bắt đầu${a.submitted_at?'<br>Nộp: '+formatDate(a.submitted_at):''}</small></td><td><strong>${esc(a.nickname||'Khách đã đăng ký')}</strong><small>${esc(a.username||'Guest')} · ${a.owner_kind==='guest'?'Khách':a.role==='student'?'Học viên':esc(a.role||'')}</small></td><td>${esc(e?.title||a.exam_id)}<small>${esc(e?.level||'')} · ${esc(e?.number||'')}</small></td><td><span class="activity-status ${a.submitted_at?'submitted':''}">${a.submitted_at?'Đã nộp bài':'Đang làm bài'}</span></td><td>${a.total_score!==null?'<strong>'+Number(a.total_score)+'</strong>/100':'—'}</td><td>${button((a.submitted_at?'Xem kết quả':'Xem bài')+' '+uiIcon('arrow'),'staff-attempt','ghost',`data-id="${esc(a.id)}" ${!e?'disabled':''}`)}</td></tr>`;}).join('')}</tbody></table></div><div class="activity-pagination">${button('Trang trước','activity-previous','ghost',activityOffset===0?'disabled':'')}<span class="small muted">${activityOffset+1}–${activityOffset+activities.length}</span>${button('Trang sau','activity-next','ghost',activities.length<50?'disabled':'')}</div>`:`<div class="history-empty">${uiIcon('file')}<h3>Chưa có bài làm phù hợp</h3><p>Nhật ký sẽ cập nhật khi học viên bắt đầu hoặc nộp bài.</p></div>`;}
function staffView(){return activityView()+staffManagementView();}
async function afterLogin(){session=await api('session');window.dispatchEvent(new Event('wewin-authenticated'));if(session.user?.mustChangePassword)return showPassword();if(modal.open)modal.close();if(session.user.role==='student'){await refreshHistory();navigate('dashboard');}else{await loadStaff();}}
async function loadStaff(){try{staff=await api('staff');await loadActivity();navigate('staff');}catch(e){notify(e);}}
function staffManagementView(){if(!staff)return '<p>Đang tải dữ liệu quản lý…</p>';const admin=session.user.role==='admin';return `<div class="dashboard-heading"><div class="eyebrow">WeWIN · ${admin?'Admin':'Giáo viên'}</div><h1>${admin?'Quản lý học tập':'Lớp học của tôi'}</h1><p>Chỉ giáo viên được phân công mới xem và nhận xét bài của học sinh trong lớp.</p></div>${admin?`<details class="management-block"><summary>Tạo tài khoản</summary><form id="create-user-form" class="management-form"><label>Tên đăng nhập<input name="username" required pattern="[a-zA-Z0-9._-]{3,80}" autocomplete="off"></label><label>Tên / biệt danh công khai<input name="nickname" maxlength="60" required></label><label>Vai trò<select name="role"><option value="student">Học sinh</option><option value="teacher">Giáo viên</option><option value="admin">Admin</option></select></label><label>Mật khẩu tạm<input name="password" type="password" minlength="10" maxlength="128" required autocomplete="new-password"></label><p class="form-error" role="alert"></p><button class="btn primary">Tạo tài khoản</button></form></details><details class="management-block"><summary>Lớp học và hạn mức AI</summary><form id="create-class-form" class="management-form"><label>Tên lớp<input name="name" required maxlength="100"></label><label>Giáo viên<select name="teacherId"><option value="">Chưa phân công</option>${staff.users.filter(u=>u.role==='teacher').map(u=>`<option value="${u.id}">${esc(u.nickname)}</option>`).join('')}</select></label><p class="form-error" role="alert"></p><button class="btn">Tạo lớp</button></form><form id="enroll-form" class="management-form"><label>Lớp<select name="classId" required>${staff.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Học sinh<select name="studentId" required>${staff.users.filter(u=>u.role==='student').map(u=>`<option value="${u.id}">${esc(u.nickname)}</option>`).join('')}</select></label><p class="form-error" role="alert"></p><button class="btn">Thêm học sinh vào lớp</button></form><form id="settings-form" class="management-form"><label>Lượt AI / học sinh / ngày<input name="dailyAiLimit" type="number" min="1" max="100" value="${staff.dailyAiLimit}" required></label><p class="form-error" role="alert"></p><button class="btn">Lưu hạn mức</button></form></details>`:''}<section class="management-block"><h2>${admin?'Tài khoản':'Học sinh trong lớp'}</h2>${staff.users.length?`<div class="table-scroll"><table class="results-table"><thead><tr><th>Biệt danh</th><th>Tài khoản</th><th>Vai trò</th><th>Trạng thái</th><th></th></tr></thead><tbody>${staff.users.map(u=>`<tr><td>${esc(u.nickname)}</td><td>${esc(u.username)}</td><td>${u.role}</td><td>${u.active?'Hoạt động':'Đã khóa'}</td><td>${u.role==='student'?button('Xem bài','staff-history','ghost',`data-id="${u.id}"`):''}${admin?button('Sửa','edit-user','ghost',`data-id="${u.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-copy">Chưa có học sinh được phân công.</p>'}</section>${staffStudent?`<section class="management-block"><h2>Bài làm · ${esc(staff.users.find(u=>u.id===staffStudent)?.nickname||'Học sinh')}</h2>${historyTable(staffAttempts,true)}</section>`:''}${selectedStaffAttempt?staffAttemptView():''}`;}
function staffAttemptView(){const a=selectedStaffAttempt.attempt,e=allExams.find(e=>e.id===a.exam_id),p=e.reading.find(p=>p.manual),r=selectedStaffAttempt.review,v=r?.teacher_override||r?.original;return `<section class="management-block staff-attempt"><h2>${esc(e.title)}</h2>${a.result?scoreCards(a.result):'<p>Bài chưa nộp.</p>'}${a.result?objectiveReview(a.result):''}${p?p.questions.map(q=>`<h3>${esc(q.prompt)}</h3><p class="submitted-writing">${esc(a.writing[q.id]||'Chưa viết')}</p>`).join(''):''}${v?`${feedbackView(r)}<details><summary>Điều chỉnh nhận xét Writing</summary><form id="override-form" class="management-form" data-attempt="${a.id}"><label>Mức độ hoàn thành<textarea name="completion" required>${esc(v.completion)}</textarea></label><div id="correction-editors">${v.corrections.map((c,i)=>`<fieldset data-correction="${i}"><legend>Lỗi ${i+1}</legend><label>Bé viết<textarea name="original-${i}">${esc(c.original)}</textarea></label><label>Câu sửa<textarea name="corrected-${i}">${esc(c.corrected)}</textarea></label><label>Giải thích<textarea name="explanation-${i}">${esc(c.explanation)}</textarea></label><button type="button" class="btn ghost" data-action="remove-correction">Bỏ mục này</button></fieldset>`).join('')}</div><button type="button" class="btn" data-action="add-correction">Thêm lỗi cần sửa</button><label>Gợi ý từ vựng (mỗi dòng một gợi ý)<textarea name="vocabulary">${esc(v.vocabulary.join('\n'))}</textarea></label>${v.maxScore===6?v.itemScores.map((score,i)=>`<label>Câu ${i+1}<select name="item-${i}"><option value="0" ${score===0?'selected':''}>0</option><option value="1" ${score===1?'selected':''}>1</option></select></label>`).join(''):`<label>Điểm /5<input name="score" type="number" min="0" max="5" value="${v.score}" required></label>`}<label>Bài tham khảo<textarea name="sample">${esc(v.sample)}</textarea></label><label>Lý do điều chỉnh<textarea name="reason" required maxlength="1000"></textarea></label><p class="form-error" role="alert"></p><button class="btn primary">Lưu nhận xét giáo viên</button></form></details><details><summary>Lịch sử nhận xét</summary><div id="review-audit">${button('Xem lịch sử','review-audit','',`data-id="${a.id}"`)}</div></details>`:p?'<p class="empty-copy">Chưa có kết quả AI. Học sinh có thể yêu cầu chấm sau khi nộp bài.</p>':''}</section>`;}
function persist(){if(!attempt)return;try{sessionStorage.setItem(localKey(),JSON.stringify({id:attempt.id,answers,writing,updated:Date.now()}));}catch{}}
function scheduleSave(){persist();saveMessage='Saving…';if(byId('save-status'))byId('save-status').textContent=saveMessage;clearTimeout(draftTimer);draftTimer=setTimeout(()=>{pendingDraft=saveDraft();},650);}
async function saveDraft(){if(!attempt||screen!=='exam'||attempt.submitted_at)return;try{await api('draft',{id:attempt.id,data:{answers,writing}});saveMessage='Saved';}catch{saveMessage='Saved on this device · reconnect to sync';}if(byId('save-status'))byId('save-status').textContent=saveMessage;}
async function begin(){if(busy)return;busy=true;render();try{const data=await api('attempts',{data:{examId:exam.id}});attempt=data.attempt;answers=attempt.answers||{};writing=attempt.writing||{};try{const local=JSON.parse(sessionStorage.getItem(localKey()));if(local?.id===attempt.id&&local.updated>new Date(attempt.updated_at).getTime()){answers=local.answers;writing=local.writing;}}catch{}selectedName='';undo=[];partIndex=0;skill='reading';screen='exam';errorMessage='';saveMessage='Saved';}catch(e){notify(e);}finally{busy=false;render();}}
async function submitAttempt(){if(busy)return;busy=true;const submitButton=modal.querySelector('[data-action="confirm-submit"]');if(submitButton){submitButton.disabled=true;submitButton.textContent='Submitting…';}clearTimeout(draftTimer);persist();try{if(pendingDraft)await pendingDraft;const response=await api('submit',{id:attempt.id,data:{answers,writing}});attempt=response.attempt;review=null;await refreshHistory();modal.close();navigate('result');loadBoard();if(session.user?.role==='student'&&exam.reading.some(p=>p.manual))assess();}catch(e){notify(e);const status=modal.querySelector('[role="alert"]');if(status)status.textContent=e.message;}finally{busy=false;if(submitButton?.isConnected){submitButton.disabled=false;submitButton.textContent='Submit and view results';}}}
async function assess(){if(review?.status==='processing')return;const attemptId=attempt.id;try{review={status:'processing',updated_at:new Date().toISOString()};render();const response=await api('writing',{id:attemptId,data:{}});if(attempt?.id!==attemptId)return;review=response.review;if(screen==='result'){render();if(review?.status==='processing')pollReview();}}catch(e){if(attempt?.id!==attemptId)return;review={status:'failed'};if(screen==='result')render();notify(e);}}
async function pollReview(){clearTimeout(reviewTimer);if(screen!=='result'||!attempt)return;reviewTimer=setTimeout(async()=>{try{const data=await api('attempt',{id:attempt.id});review=data.review;if(review?.status==='processing'&&Date.now()-new Date(review.updated_at).getTime()>125000)review={...review,status:'failed'};if(screen==='result'){render();if(review?.status==='processing')pollReview();}}catch{}},5000);}
function selectName(name,redraw=true){selectedName=name;if(redraw)render();else{root.querySelectorAll('[data-name]').forEach(el=>{el.setAttribute('aria-pressed',el.dataset.name===name);el.querySelector('rect')?.classList.toggle('chosen',el.dataset.name===name);});}}
function connect(name,id){const p=currentPart(),s=p.interaction;name=name||selectedName;if(!name||name===s.example.name||id===s.example.target)return;const next={...answers[p.id]};for(const key of Object.keys(next))if(next[key]===id)delete next[key];next[name]=id;if(Object.keys(next).length>5){announce('Draw five lines. Erase a line before adding another name.');return;}answers[p.id]=next;selectedName=name;scheduleSave();render();announce(`${name} linked. You can change the line.`);}
function pictureSnapshot(){undo.push(JSON.stringify(answers[currentPart().id]||{}));if(undo.length>20)undo.shift();}
function selectRegion(id){const p=currentPart(),areas=answers[p.id]||{};if(tool==='erase'){pictureSnapshot();const next={...areas};delete next[id];answers[p.id]=next;scheduleSave();render();return;}if(tool==='write'){wordArea=id;render();byId('picture-word-input')?.focus({preventScroll:true});return;}
 const painted=Object.values(areas).filter(v=>v.color).length;if(!areas[id]?.color&&painted>=p.interaction.paintCount)return announce(`You have coloured ${p.interaction.paintCount} objects. Erase one to change it.`);pictureSnapshot();answers[p.id]={...areas,[id]:{...areas[id],color}};scheduleSave();render();}
const timeLabel=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;
function audioUI(){const play=byId('audio-play');if(play){play.textContent=audio.paused?'▶':'❚❚';play.setAttribute('aria-label',audio.paused?'Play audio':'Pause audio');}const seek=byId('audio-seek');if(seek){seek.max=Number.isFinite(audio.duration)?audio.duration:1;seek.value=audio.currentTime||0;seek.disabled=!Number.isFinite(audio.duration);}if(byId('audio-time'))byId('audio-time').textContent=`${timeLabel(audio.currentTime||0)} / ${Number.isFinite(audio.duration)?timeLabel(audio.duration):'--:--'}`;}
function syncAudio(){if(screen!=='exam'||skill!=='listening'){audio.pause();return;}const src='assets/'+exam.audio[partIndex]+'?v='+(exam.audioVersion||exam.version);if(src!==audioSource){audio.pause();audioSource=src;audio.src=src;audio.load();}audioUI();}
async function play(){try{await audio.play();if(byId('audio-error'))byId('audio-error').hidden=true;}catch{showAudioError();}}
function showAudioError(){if(byId('audio-error')){byId('audio-error').hidden=false;byId('audio-error').textContent='Unable to play this recording. Check your connection and try again.';}}
for(const event of ['loadedmetadata','durationchange','play','pause','timeupdate','ended'])audio.addEventListener(event,audioUI);audio.addEventListener('error',showAudioError);
document.addEventListener('input',event=>{const el=event.target;if(el.id==='catalog-search'){query=el.value;limit=6;byId('catalog-results').innerHTML=catalogResults();return;}if(el.dataset.question){answers[el.dataset.question]=el.value;scheduleSave();}if(el.dataset.writing){writing[el.dataset.writing]=el.value;const count=byId('words-'+el.dataset.writing);if(count)count.textContent=wordCount(el.value)+' words · Write 20 or more words';scheduleSave();}if(el.id==='audio-seek'&&Number.isFinite(audio.duration))audio.currentTime=Number(el.value);
 if(el.dataset.wordRegion){const p=currentPart(),areas=answers[p.id]||{},id=el.dataset.wordRegion;const count=Object.values(areas).filter(v=>v.word).length;if(!areas[id]?.word&&el.value.trim()&&count>=p.interaction.writeCount){el.value='';announce('Erase an existing word before writing in a new place.');return;}if(!el.dataset.snapshot){pictureSnapshot();el.dataset.snapshot='true';}answers[p.id]={...areas,[id]:{...areas[id],word:el.value}};scheduleSave();root.querySelectorAll(`[data-region="${id}"] .picture-word`).forEach(node=>node.textContent=el.value);}
});
document.addEventListener('change',async event=>{if(event.target.id==='activity-status'||event.target.id==='activity-student'){activityStatus=byId('activity-status').value;activityStudent=byId('activity-student').value;activityOffset=0;byId('activity-results').textContent='Đang tải nhật ký…';if(await loadActivity()){const target=byId('activity-results');if(target)target.innerHTML=activityResults();}}if(event.target.id==='board-level'){boardLevel=event.target.value;boardExam=allExams.find(e=>e.levelKey===boardLevel).id;render();loadBoard();}if(event.target.id==='board-exam'){boardExam=event.target.value;loadBoard();}});
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const {action,value,id}=el.dataset;event.preventDefault();try{
 if(action==='catalog'){category='all';navigate('catalog');return;}
 if(action==='library-level'){category=value;limit=6;navigate('catalog');byId('catalog')?.scrollIntoView({block:'start'});return;}
 if(action==='my-history'){if(session.user&&session.user.role!=='student'){await loadStaff();byId('staff-activity')?.scrollIntoView({block:'start'});return;}await refreshHistory();navigate('history');return;}
 if(action==='refresh-history'){el.disabled=true;await refreshHistory();render();return;}
 if(['refresh-activity','activity-previous','activity-next'].includes(action)){el.disabled=true;if(action==='activity-previous')activityOffset=Math.max(0,activityOffset-50);if(action==='activity-next')activityOffset+=50;if(await loadActivity()){const target=byId('activity-results');if(target)target.innerHTML=activityResults();}el.disabled=false;return;}
 if(action==='login')return showLogin();
 if(action==='logout'){await api('logout',{data:{}});session=await api('session');attempt=null;answers={};writing={};history=[];staff=null;selectedStaffAttempt=null;review=null;boardEntries=[];navigate('catalog');if(!session.registered)gatePromise=requireLeadAccess();return;}
 if(action==='close-modal'){modal.close();return;}
 if(action==='open-test'){exam=allExams.find(e=>e.id===el.dataset.exam)||exam;attempt=null;partIndex=0;skill='reading';navigate('intro');return;}
 if(action==='category'||action==='level-card'){category=value;limit=6;render();if(action==='level-card')byId('catalog').scrollIntoView({block:'start'});return;}
 if(action==='more-tests'){limit+=6;byId('catalog-results').innerHTML=catalogResults();return;}
 if(action==='clear-catalog'){query='';category='all';limit=6;render();byId('catalog-search').focus({preventScroll:true});return;}
 if(action==='help'){const en=['intro','exam','result','board'].includes(screen);return openModal(`<h2>${en?'Choose a level':'Chọn cấp độ phù hợp'}</h2><div class="level-help-list"><p><strong>Pre A1 Starters</strong><span>${en?'Start with familiar words and simple sentences.':'Bắt đầu với từ vựng quen thuộc và câu đơn giản.'}</span></p><p><strong>A1 Movers</strong><span>${en?'Build confidence with longer texts and recordings.':'Luyện thêm với đoạn văn và bài nghe dài hơn.'}</span></p><p><strong>A2 Flyers</strong><span>${en?'Try more detailed texts and an open writing task.':'Thử sức với nội dung nhiều chi tiết và bài viết mở.'}</span></p></div><p>${en?'Choose the level you are currently studying. The practice score is not a placement test.':'Ưu tiên cấp độ bé đang học. Điểm luyện tập không dùng để xác định trình độ Cambridge chính thức.'}</p>${button(en?'Close':'Đã hiểu','close-modal','primary')}`);}
 if(action==='start')return begin();
 if(action==='skill'||action==='part'||action==='previous'||action==='next'){if(action==='skill'){skill=value;partIndex=0;}if(action==='part')partIndex=Number(value);if(action==='previous')partIndex=Math.max(0,partIndex-1);if(action==='next'){if(partIndex===exam[skill].length-1)return openSubmit();partIndex++;}selectedName='';wordArea='';undo=[];render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(action==='answer'){answers[el.dataset.question]=value;scheduleSave();render();return;}
 if(action==='play'){if(audio.paused)await play();else audio.pause();return;}
 if(action==='restart-audio'){audio.currentTime=0;return play();}
 if(action==='picture-tool'){tool=value;wordArea='';render();return;}
 if(action==='picture-colour'){color=value;render();return;}
 if(action==='finish-word'){wordArea='';render();return;}
 if(action==='undo-picture'&&undo.length){answers[currentPart().id]=JSON.parse(undo.pop());scheduleSave();render();return;}
 if(action==='remove-line'){if(selectedName){const next={...answers[currentPart().id]};delete next[selectedName];answers[currentPart().id]=next;scheduleSave();render();}return;}
 if(action==='zoom-page'){openModal(`<div class="zoom-header"><h2>Question page</h2>${button('Close','close-modal')}</div>${image(el.dataset.image,'Enlarged question page','zoom-image')}`,'zoom-dialog');return;}
 if(action==='zoom-picture'){openModal(`<div class="zoom-header"><h2>Picture</h2>${button('Close','close-modal')}</div><p>Close this view to draw, colour or write.</p>${currentPart().interaction.type==='match'?matchScene(currentPart(),answers[currentPart().id]||{},''):paintScene(currentPart(),answers[currentPart().id]||{})}`,'zoom-dialog picture-zoom');return;}
 if(action==='submit')return openSubmit();if(action==='confirm-submit')return submitAttempt();
 if(action==='retry'){attempt=null;answers={};writing={};review=null;return begin();}
 if(action==='assess-writing'){if(review?.status==='completed')return byId('ai-feedback')?.scrollIntoView({block:'start'});return assess();}
 if(action==='board'||action==='dashboard'){if(action==='dashboard')await refreshHistory();navigate(action==='board'?'board':'dashboard');if(action==='board')loadBoard();return;}
 if(action==='load-attempt'){const data=await api('attempt',{id});attempt=data.attempt;exam=allExams.find(e=>e.id===attempt.exam_id);answers=attempt.answers;writing=attempt.writing;review=data.review;if(attempt.submitted_at){navigate('result');loadBoard();}else navigate('exam');return;}
 if(action==='staff')return loadStaff();
 if(action==='staff-history'){staffStudent=id;staffAttempts=(await api('history',{id})).attempts;selectedStaffAttempt=null;render();return;}
 if(action==='staff-attempt'){selectedStaffAttempt=await api('attempt',{id});render();document.querySelector('.staff-attempt')?.scrollIntoView({block:'start'});return;}
 if(action==='review-audit'){const data=await api('review-audit',{id});byId('review-audit').innerHTML=data.audit.length?data.audit.map(a=>`<p>${esc(new Date(a.created_at).toLocaleString('vi-VN'))} · ${esc(a.reason)} · ${a.previous_value?.score??'—'} → ${a.new_value.score}</p>`).join(''):'<p>Chưa có điều chỉnh.</p>';return;}
 if(action==='remove-correction'){el.closest('[data-correction]').remove();return;}
 if(action==='add-correction'){const container=byId('correction-editors');const indices=[...container.querySelectorAll('[data-correction]')].map(n=>Number(n.dataset.correction));const i=Math.max(-1,...indices)+1;container.insertAdjacentHTML('beforeend',`<fieldset data-correction="${i}"><legend>Lỗi ${i+1}</legend><label>Bé viết<textarea name="original-${i}"></textarea></label><label>Câu sửa<textarea name="corrected-${i}"></textarea></label><label>Giải thích<textarea name="explanation-${i}"></textarea></label><button type="button" class="btn ghost" data-action="remove-correction">Bỏ mục này</button></fieldset>`);return;}
 if(action==='edit-user'){const u=staff.users.find(u=>u.id===id);return openModal(`<h2>Sửa tài khoản ${esc(u.username)}</h2><form id="edit-user-form" class="management-form" data-id="${u.id}"><label>Biệt danh<input name="nickname" value="${esc(u.nickname)}" required></label><label>Trạng thái<select name="active"><option value="true" ${u.active?'selected':''}>Hoạt động</option><option value="false" ${!u.active?'selected':''}>Khóa tài khoản</option></select></label><label>Mật khẩu tạm mới (để trống nếu không đổi)<input type="password" name="password" minlength="10" autocomplete="new-password"></label><p class="form-error" role="alert"></p><button class="btn primary">Lưu</button>${button('Hủy','close-modal')}</form>`);}
 }catch(e){notify(e);}});
function openSubmit(){openModal(`<h2>Submit your practice?</h2><p>Unanswered questions score zero. Open writing is assessed separately from your Reading & Listening score.</p><p role="alert" class="form-error"></p><div class="dialog-actions">${button('Keep working','close-modal')}${button('Submit and view results','confirm-submit','primary')}</div>`);}
document.addEventListener('submit',async event=>{const form=event.target;if(!['login-form','password-form','create-user-form','create-class-form','enroll-form','settings-form','edit-user-form','override-form'].includes(form.id))return;event.preventDefault();const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit?.disabled)return;const data=Object.fromEntries(new FormData(form));const error=form.querySelector('.form-error');if(error)error.textContent='';if(submit)submit.disabled=true;
 try{
  if(form.id==='login-form'){await api('login',{data});await afterLogin();return;}
  if(form.id==='password-form'){await api('password',{data});modal.close();await afterLogin();return;}
  if(form.id==='create-user-form')await api('users',{data});
  if(form.id==='create-class-form')await api('classes',{data});
  if(form.id==='enroll-form')await api('enroll',{data});
  if(form.id==='settings-form')await api('settings',{data:{dailyAiLimit:Number(data.dailyAiLimit)}});
  if(form.id==='edit-user-form'){await api('user',{id:form.dataset.id,data:{nickname:data.nickname,active:data.active==='true',...(data.password?{password:data.password}:{})}});modal.close();}
  if(form.id==='override-form'){const old=selectedStaffAttempt.review.teacher_override||selectedStaffAttempt.review.original;const itemScores=old.maxScore===6?old.itemScores.map((_,i)=>Number(data['item-'+i])):[];const value={completion:data.completion,corrections:[...form.querySelectorAll('[data-correction]')].map(node=>{const i=node.dataset.correction;return {original:data['original-'+i],corrected:data['corrected-'+i],explanation:data['explanation-'+i]};}),vocabulary:data.vocabulary.split('\n').map(s=>s.trim()).filter(Boolean),score:old.maxScore===6?itemScores.reduce((a,b)=>a+b,0):Number(data.score),maxScore:old.maxScore,sample:data.sample,itemScores};await api('review-override',{id:form.dataset.attempt,data:{review:value,reason:data.reason}});selectedStaffAttempt=await api('attempt',{id:form.dataset.attempt});render();return;}
  await loadStaff();announce('Saved.');
 }catch(e){if(error)error.textContent=e.message;else notify(e);}finally{if(submit?.isConnected)submit.disabled=false;}
});
window.addEventListener('wewin-signin',showLogin);
modal.addEventListener('cancel',event=>{if(session.user?.mustChangePassword)event.preventDefault();});
try{session=await api('session');}catch(e){session={user:null,registered:false,databaseReady:false};errorMessage='Results storage is temporarily unavailable. Please try again shortly.';}
if(session.user?.role==='teacher'||session.user?.role==='admin'){staff=await api('staff').catch(()=>null);await loadActivity();screen='staff';}
else if(screen==='exam'||screen==='result'){
 const attemptId=initial.get('attempt');if(attemptId&&session.registered){try{const data=await api('attempt',{id:attemptId});attempt=data.attempt;answers=attempt.answers;writing=attempt.writing;review=data.review;screen=attempt.submitted_at?'result':'exam';}catch{screen='intro';}}else screen='intro';
}
if(!['catalog','intro','exam','result','staff','dashboard','history','board','login'].includes(screen))screen='catalog';
if(session.registered&&(!session.user||session.user.role==='student')&&!session.user?.mustChangePassword)await refreshHistory();
partIndex=Math.min(partIndex,exam[skill].length-1);render();
if(!session.registered&&screen!=='login'){gatePromise=requireLeadAccess();gatePromise.then(async()=>{session.registered=true;await refreshHistory();render();});}
if(session.user?.mustChangePassword)showPassword();
if(screen==='result'||screen==='board')loadBoard();if(screen==='result'&&review?.status==='processing')pollReview();
